"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import type {HandoffScope} from '@/lib/cashier-handoff';
export function CashierLedgerPeriodSelect({scope,disabled=false,onSelect}:{scope:HandoffScope;disabled?:boolean;onSelect:(value:{period:string;date:string}|null)=>void}){
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[period,setPeriod]=useState(''),[date,setDate]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 function choose(id:string,day:string){setPeriod(id);setDate(day);const p=setup?.periods.find(p=>p.period_id===id&&!p.closed);const valid=/^\d{4}-\d{2}-\d{2}$/.test(day)&&!Number.isNaN(Date.parse(day))&&new Date(day).toISOString().slice(0,10)===day;onSelect(p&&valid&&day>=p.start_date&&day<p.end_date_exclusive?{period:id,date:day}:null)}
 async function load(){if(disabled||lock.current)return;lock.current=true;setBusy(true);setError('');setPeriod('');setDate('');onSelect(null);try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen deposit accounting.');const data=readAccountingSetup(await hotelRpc('gl_setup',{p_tenant:scope.tenant,p_property:scope.property}),scope.tenant,scope.property);const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen deposit accounting.');if(alive.current)setSetup(data);}catch(e){if(alive.current){setSetup(null);setError(e instanceof Error?e.message:'Unable to load periods.')}}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <fieldset disabled={disabled||busy}><legend>Posting date</legend><button type="button" onClick={()=>void load()}>Load accounting periods</button>{error&&<p role="alert">{error}</p>}{setup&&<><label>Accounting period<select value={period} onChange={e=>choose(e.target.value,date)}><option value="">Choose an open period</option>{setup.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to before {p.end_date_exclusive}</option>)}</select></label><label>Transfer posting date<input type="date" value={date} onChange={e=>choose(period,e.target.value)}/></label>{!setup.periods.some(p=>!p.closed)&&<p>No open accounting periods. Configure a period in Accounting Setup.</p>}</>}</fieldset>
}
